{"command":"cat << 'EOF' > src/options.cpp
#include "options.hpp"
#include <iostream>
#include <sstream>
#include <cstring>

static std::vector<std::string> split_comma(const std::string &s) {
    std::vector<std::string> res;
    std::stringstream ss(s);
    std::string item;
    while (std::getline(ss, item, ',')) {
        if (!item.empty()) res.push_back(item);
    }
    return res;
}

bool Options::is_severity_enabled(const std::string &sev, const std::string &id) const {
    if (disabled_severities.count(sev) || disabled_severities.count(id)) return false;
    if (sev == "error" || sev == "syntaxError") return true;

    if (enabled_severities.count("all")) return true;

    if (enabled_severities.count("style") && (sev == "style" || sev == "warning" || sev == "performance" || sev == "portability")) {
        return true;
    }

    if (enabled_severities.count(sev)) return true;
    if (id == "unusedFunction" && enabled_severities.count("unusedFunction")) return true;
    if (id == "missingIncludeSystem" && (enabled_severities.count("missingInclude") || enabled_severities.count("information"))) return true;

    return false;
}

Options Options::parse(int argc, char **argv) {
    Options opt;

    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];

        if (arg == "--help" || arg == "-h") {
            opt.show_help = true;
        } else if (arg == "--version") {
            opt.show_version = true;
        } else if (arg == "-v" || arg == "--verbose") {
            opt.verbose = true;
        } else if (arg == "-q" || arg == "--quiet") {
            opt.quiet = true;
        } else if (arg == "--xml") {
            opt.xml = true;
            opt.xml_version = 2;
        } else if (arg.rfind("--xml-version=", 0) == 0) {
            opt.xml = true;
            opt.xml_version = std::stoi(arg.substr(14));
        } else if (arg == "--inline-suppr") {
            opt.inline_suppr = true;
        } else if (arg == "-E") {
            opt.preprocess_only = true;
        } else if (arg == "--check-config") {
            opt.check_config = true;
        } else if (arg == "--check-library") {
            opt.check_library = true;
        } else if (arg == "--dump") {
            opt.dump_ast = true;
        } else if (arg.rfind("--error-exitcode=", 0) == 0) {
            opt.error_exitcode = std::stoi(arg.substr(17));
        } else if (arg == "--error-exitcode" && i + 1 < argc) {
            opt.error_exitcode = std::stoi(argv[++i]);
        } else if (arg.rfind("--enable=", 0) == 0) {
            for (auto &s : split_comma(arg.substr(9))) {
                opt.enabled_severities.insert(s);
            }
        } else if (arg == "--enable" && i + 1 < argc) {
            for (auto &s : split_comma(argv[++i])) {
                opt.enabled_severities.insert(s);
            }
        } else if (arg.rfind("--disable=", 0) == 0) {
            for (auto &s : split_comma(arg.substr(10))) {
                opt.disabled_severities.insert(s);
            }
        } else if (arg == "--disable" && i + 1 < argc) {
            for (auto &s : split_comma(argv[++i])) {
                opt.disabled_severities.insert(s);
            }
        } else if (arg.rfind("--template=", 0) == 0) {
            opt.template_format = arg.substr(11);
        } else if (arg == "--template" && i + 1 < argc) {
            opt.template_format = argv[++i];
        } else if (arg.rfind("--template-location=", 0) == 0) {
            opt.template_location_format = arg.substr(20);
        } else if (arg == "--template-location" && i + 1 < argc) {
            opt.template_location_format = argv[++i];
        } else if (arg.rfind("--suppress=", 0) == 0) {
            opt.raw_suppressions.push_back(arg.substr(11));
        } else if (arg == "--suppress" && i + 1 < argc) {
            opt.raw_suppressions.push_back(argv[++i]);
        } else if (arg.rfind("--suppressions-list=", 0) == 0) {
            opt.suppressions_files.push_back(arg.substr(20));
        } else if (arg == "--suppressions-list" && i + 1 < argc) {
            opt.suppressions_files.push_back(argv[++i]);
        } else if (arg.rfind("--checkers-report=", 0) == 0) {
            opt.checkers_report_file = arg.substr(18);
        } else if (arg == "--checkers-report" && i + 1 < argc) {
            opt.checkers_report_file = argv[++i];
        } else if (arg.rfind("--std=", 0) == 0) {
