#include "suppressions.hpp"
#include <fstream>
#include <sstream>
#include <iostream>
#include <algorithm>

static std::string trim(const std::string &s) {
    auto start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return "";
    auto end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);
}

static bool filename_matches(const std::string &pattern, const std::string &filename) {
    if (pattern.empty() || pattern == "*") return true;
    if (pattern == filename) return true;
    // Check if pattern is suffix or basename
    if (filename.length() > pattern.length() &&
        filename.compare(filename.length() - pattern.length(), pattern.length(), pattern) == 0) {
        return true;
    }
    return false;
}

void Suppressors::add_rule(const std::string &spec) {
    std::string s = trim(spec);
    if (s.empty()) return;

    Suppression rule;
    size_t pos1 = s.find(':');
    if (pos1 == std::string::npos) {
        rule.id = s;
    } else {
        rule.id = s.substr(0, pos1);
        std::string rest = s.substr(pos1 + 1);
        size_t pos2 = rest.find(':');
        if (pos2 == std::string::npos) {
            rule.filename = rest;
        } else {
            rule.filename = rest.substr(0, pos2);
            std::string line_str = rest.substr(pos2 + 1);
            if (!line_str.empty() && line_str != "*") {
                try { rule.line = std::stoi(line_str); } catch(...) {}
            }
        }
    }
    rules.push_back(rule);
}

void Suppressors::load_file(const std::string &filepath) {
    std::ifstream ifs(filepath);
    if (!ifs.is_open()) return;
    std::string line;
    while (std::getline(ifs, line)) {
        add_rule(line);
    }
}

bool Suppressors::is_suppressed(const Error &err) const {
    for (const auto &r : rules) {
        bool id_match = (r.id == "*" || r.id == err.id);
        bool file_match = filename_matches(r.filename, err.file);
        bool line_match = (r.line == 0 || r.line == err.line);

        if (id_match && file_match && line_match) {
            return true;
        }
    }
    return false;
}
EOF"}

