                try { rule.line = std::stoi(line_str); } catch(...) {}
            }
        }
    }
    rules.push_back(rule);
}

void Suppressors::load_file(const std::string &filepath) {
    std::ifstream ifs(filepath);
    if (!ifs.is_open()) return;
    std::string line;
    while (std::getline(ifs, line)) {
        add_rule(line);
    }
}

bool Suppressors::is_suppressed(const Error &err) const {
    for (const auto &r : rules) {
        bool id_match = (r.id == "*" || r.id == err.id);
        bool file_match = filename_matches(r.filename, err.file);
        bool line_match = (r.line == 0 || r.line == err.line);

        if (id_match && file_match && line_match) {
            return true;
        }
    }
    return false;
}
