    }

    for (const auto &kv : funcs) {
        if (!called_funcs.count(kv.first)) {
            Error err;
            err.id = "unusedFunction";
            err.severity = "style";
            err.cwe = 561;
            err.msg = "The function '" + kv.first + "' is never used.";
            err.file = filepath;
            err.line = kv.second.first;
            err.column = kv.second.second;
            err.symbol = kv.first;
            if (kv.second.first > 0 && kv.second.first <= (int)lines.size()) {
                err.code_line = lines[kv.second.first - 1].raw_line;
            }
            errors.push_back(err);
        }
    }

    // Filter by suppressions and inline suppressions
    std::vector<Error> filtered_errors;
    for (const auto &err : errors) {
        if (!opt.is_severity_enabled(err.severity, err.id)) continue;
        if (supp.is_suppressed(err)) continue;

        // Inline suppression check
        if (opt.inline_suppr && err.line > 0 && err.line <= (int)lines.size()) {
            std::string supp_id = lines[err.line - 1].inline_suppress_id;
            if (err.line > 1 && supp_id.empty()) {
                supp_id = lines[err.line - 2].inline_suppress_id;
            }
            if (!supp_id.empty() && (supp_id == "*" || supp_id == err.id)) {
                continue;
            }
        }

        filtered_errors.push_back(err);
    }

    return filtered_errors;
}
