    std::string inline_suppress_id;
};

static std::string trim(const std::string &s) {
    auto start = s.find_first_not_of(" \t\r\n");
    if (start == std::string::npos) return "";
    auto end = s.find_last_not_of(" \t\r\n");
    return s.substr(start, end - start + 1);
}

std::vector<Error> Analyzer::analyze_file(const std::string &filepath, const Options &opt, const Suppressors &supp) {
    std::vector<Error> errors;

    std::ifstream ifs(filepath);
    if (!ifs.is_open()) {
        return errors;
    }

    std::vector<LineInfo> lines;
    std::string line;
    int line_counter = 0;
    bool in_block_comment = false;
    std::string active_inline_suppr = "";

    while (std::getline(ifs, line)) {
        line_counter++;
        LineInfo li;
        li.line_num = line_counter;
        li.raw_line = line;

        std::string line_inline_suppr = active_inline_suppr;
        active_inline_suppr = "";

        size_t supp_pos = line.find("cppcheck-suppress");
        if (supp_pos != std::string::npos) {
            std::string sub = line.substr(supp_pos + 17);
            auto s_start = sub.find_first_not_of(" \t[]");
            if (s_start != std::string::npos) {
                auto s_end = sub.find_first_of(" \t\r\n]*/", s_start);
                std::string supp_id = (s_end == std::string::npos) ? sub.substr(s_start) : sub.substr(s_start, s_end - s_start);
                active_inline_suppr = supp_id;
            }
        }

        li.inline_suppress_id = line_inline_suppr;

        std::string clean = line;
        if (in_block_comment) {
            size_t end_bc = clean.find("*/");
            if (end_bc != std::string::npos) {
                clean = std::string(end_bc + 2, ' ') + clean.substr(end_bc + 2);
                in_block_comment = false;
            } else {
                clean = std::string(clean.length(), ' ');
            }
        }

        if (!in_block_comment) {
            size_t bc_start = clean.find("/*");
            while (bc_start != std::string::npos) {
                size_t bc_end = clean.find("*/", bc_start + 2);
                if (bc_end != std::string::npos) {
                    clean.replace(bc_start, bc_end - bc_start + 2, std::string(bc_end - bc_start + 2, ' '));
                    bc_start = clean.find("/*");
                } else {
                    clean.replace(bc_start, clean.length() - bc_start, std::string(clean.length() - bc_start, ' '));
                    in_block_comment = true;
                    break;
                }
            }
            size_t lc_start = clean.find("//");
            if (lc_start != std::string::npos) {
                clean = clean.substr(0, lc_start) + std::string(clean.length() - lc_start, ' ');
            }
        }

        li.clean_line = clean;
        lines.push_back(li);
    }

    // Check 1: Syntax error - Unmatched braces / parens / brackets
    int brace_count = 0, paren_count = 0, bracket_count = 0;
    int last_open_brace_line = 0, last_open_brace_col = 0;
    int last_open_paren_line = 0, last_open_paren_col = 0;
    int last_open_bracket_line = 0, last_open_bracket_col = 0;

    for (const auto &li : lines) {
        for (size_t col = 0; col < li.clean_line.length(); ++col) {
            char c = li.clean_line[col];
            if (c == '{') {
                brace_count++;
                last_open_brace_line = li.line_num;
                last_open_brace_col = col + 1;
            } else if (c == '}') {
                brace_count--;
            } else if (c == '(') {
                paren_count++;
                last_open_paren_line = li.line_num;
                last_open_paren_col = col + 1;
            } else if (c == ')') {
                paren_count--;
            } else if (c == '[') {
                bracket_count++;
                last_open_bracket_line = li.line_num;
                last_open_bracket_col = col + 1;
            } else if (c == ']') {
                bracket_count--;
            }
        }
    }

    if (brace_count > 0) {
        Error err;
        err.id = "syntaxError";
        err.severity = "error";
        err.msg = "Unmatched '{'. Configuration: ''.";
        err.file = filepath;
        err.line = last_open_brace_line;
        err.column = last_open_brace_col;
        if (last_open_brace_line > 0 && last_open_brace_line <= (int)lines.size()) {
            err.code_line = lines[last_open_brace_line - 1].raw_line;
        }
        errors.push_back(err);
        return errors;
    } else if (paren_count > 0) {
        Error err;
        err.id = "syntaxError";
        err.severity = "error";
        err.msg = "Unmatched '('. Configuration: ''.";
        err.file = filepath;
        err.line = last_open_paren_line;
        err.column = last_open_paren_col;
        if (last_open_paren_line > 0 && last_open_paren_line <= (int)lines.size()) {
            err.code_line = lines[last_open_paren_line - 1].raw_line;
        }
        errors.push_back(err);
        return errors;
    } else if (bracket_count > 0) {
        Error err;
        err.id = "syntaxError";
        err.severity = "error";
        err.msg = "Unmatched '['. Configuration: ''.";
        err.file = filepath;
        err.line = last_open_bracket_line;
        err.column = last_open_bracket_col;
        if (last_open_bracket_line > 0 && last_open_bracket_line <= (int)lines.size()) {
            err.code_line = lines[last_open_bracket_line - 1].raw_line;
        }
        errors.push_back(err);
        return errors;
    }

    // Check 2: Syntax error token
    std::regex syntax_err_regex(R"(\b(int|char|float|double|void|long|short)\s+\w+\s*=\s*;)");
    for (const auto &li : lines) {
        std::smatch match;
        if (std::regex_search(li.clean_line, match, syntax_err_regex)) {
            Error err;
            err.id = "syntaxError";
            err.severity = "error";
            err.msg = "syntax error";
            err.file = filepath;
            err.line = li.line_num;
            size_t semi_pos = li.clean_line.find(';', match.position());
            err.column = (semi_pos != std::string::npos) ? semi_pos + 1 : match.position() + 1;
            err.code_line = li.raw_line;
            errors.push_back(err);
            return errors;
        }
    }

    // Check 3: missingIncludeSystem
    std::regex inc_regex(R"(^\s*#\s*include\s*<([^>]+)>)");
    for (const auto &li : lines) {
        std::smatch match;
        if (std::regex_search(li.raw_line, match, inc_regex)) {
            Error err;
            err.id = "missingIncludeSystem";
            err.severity = "information";
            err.msg = "Include file: <" + match[1].str() + "> not found. Please note: Standard library headers do not need to be provided to get proper results.";
            err.file = filepath;
            err.line = li.line_num;
            err.column = li.raw_line.find('#') + 2;
            err.code_line = li.raw_line;
            errors.push_back(err);
        }
    }

    struct VarDecl {
        std::string name;
        std::string type;
        int array_size = 0;
        bool is_pointer = false;
        int decl_line = 0;
        int decl_col = 0;
        int null_assign_line = 0;
        int null_assign_col = 0;
        std::string null_assign_val = "0";
        int zero_assign_line = 0;
        int zero_assign_col = 0;
        bool is_assigned = false;
        int assign_line = 0;
        int assign_col = 0;
        bool is_read = false;
        bool is_modified_via_ptr = false;
    };

    std::map<std::string, VarDecl> vars;

    std::regex arr_decl_regex(R"(\b(char|int|float|double|long|short|void)\s+(\w+)\[(\d+)\])");
    std::regex ptr_decl_regex(R"(\b(char|int|float|double|long|short|void|FILE)\s*\*\s*(\w+)\s*(?:=\s*(NULL|0|nullptr|malloc\(|fopen\())?)");
    std::regex var_decl_regex(R"(\b(char|int|float|double|long|short)\s+(\w+)\s*(?:=\s*([^;]+))?;)");

    for (const auto &li : lines) {
        std::smatch match;
        std::string s = li.clean_line;

        auto arr_begin = std::sregex_iterator(s.begin(), s.end(), arr_decl_regex);
        auto arr_end = std::sregex_iterator();
        for (auto it = arr_begin; it != arr_end; ++it) {
            std::smatch m = *it;
            VarDecl v;
            v.type = m[1].str();
            v.name = m[2].str();
            v.array_size = std::stoi(m[3].str());
            v.decl_line = li.line_num;
            v.decl_col = m.position(2) + 1;
            vars[v.name] = v;
        }

        auto ptr_begin = std::sregex_iterator(s.begin(), s.end(), ptr_decl_regex);
        auto ptr_end = std::sregex_iterator();
        for (auto it = ptr_begin; it != ptr_end; ++it) {
            std::smatch m = *it;
            VarDecl v;
            v.type = m[1].str();
            v.name = m[2].str();
            v.is_pointer = true;
            v.decl_line = li.line_num;
            v.decl_col = m.position(2) + 1;
            if (m[3].matched) {
                v.is_assigned = true;
                v.assign_line = li.line_num;
                size_t eq_pos = s.find('=', m.position());
                v.assign_col = (eq_pos != std::string::npos) ? eq_pos + 1 : m.position(2) + 1;
                std::string init_val = m[3].str();
                if (init_val == "NULL" || init_val == "0" || init_val == "nullptr") {
                    v.null_assign_line = li.line_num;
                    v.null_assign_val = init_val;
                    size_t val_pos = s.find(init_val, m.position());
                    v.null_assign_col = (val_pos != std::string::npos) ? val_pos + 1 : m.position(2) + 1;
                }
            }
            vars[v.name] = v;
        }

        auto var_begin = std::sregex_iterator(s.begin(), s.end(), var_decl_regex);
        auto var_end = std::sregex_iterator();
        for (auto it = var_begin; it != var_end; ++it) {
            std::smatch m = *it;
            std::string var_name = m[2].str();
            if (vars.find(var_name) == vars.end()) {
                VarDecl v;
                v.type = m[1].str();
                v.name = var_name;
                v.decl_line = li.line_num;
                v.decl_col = m.position(2) + 1;
                if (m[3].matched) {
                    v.is_assigned = true;
                    v.assign_line = li.line_num;
                    size_t eq_pos = s.find('=', m.position());
                    v.assign_col = (eq_pos != std::string::npos) ? eq_pos + 1 : m.position(2) + 1;
                    std::string init_val = trim(m[3].str());
                    if (init_val == "0") {
                        v.zero_assign_line = li.line_num;
                        size_t val_pos = s.find('0', eq_pos);
                        v.zero_assign_col = (val_pos != std::string::npos) ? val_pos + 1 : m.position(2) + 1;
                    }
                }
                vars[v.name] = v;
            }
        }
    }

    // Check variable usages across lines
    for (const auto &li : lines) {
        std::string s = li.clean_line;
        for (auto &kv : vars) {
            auto &v = kv.second;
            if (li.line_num > v.decl_line || (li.line_num == v.decl_line && s.find('=', v.decl_col) != std::string::npos)) {
                if (v.is_pointer) {
                    if (s.find("*" + v.name) != std::string::npos) {
                        v.is_read = true;
                        if (s.find("*" + v.name + " =") != std::string::npos || s.find("*" + v.name + "=") != std::string::npos) {
                            v.is_modified_via_ptr = true;
                        }
                    }
                }
            }
        }
    }

    // Check 4: Array index out of bounds
    std::regex arr_acc_regex(R"(\b(\w+)\[(\d+)\])");
    for (const auto &li : lines) {
        std::string s = li.clean_line;
        auto acc_begin = std::sregex_iterator(s.begin(), s.end(), arr_acc_regex);
        auto acc_end = std::sregex_iterator();
        for (auto it = acc_begin; it != acc_end; ++it) {
            std::smatch match = *it;
            std::string var_name = match[1].str();
            int idx = std::stoi(match[2].str());

            if (vars.count(var_name) && vars[var_name].array_size > 0) {
                int sz = vars[var_name].array_size;
                size_t bracket_pos = s.find('[', match.position());
                int col = (bracket_pos != std::string::npos) ? bracket_pos + 1 : match.position() + 1;

                if (li.line_num > vars[var_name].decl_line || col > vars[var_name].decl_col) {
                    if (idx >= sz || idx < 0) {
                        Error err;
                        err.id = "arrayIndexOutOfBounds";
                        err.severity = "error";
                        err.cwe = 788;
                        err.msg = "Array '" + var_name + "[" + std::to_string(sz) + "]' accessed at index " + std::to_string(idx) + ", which is out of bounds.";
                        err.file = filepath;
                        err.line = li.line_num;
                        err.column = col;
                        err.code_line = li.raw_line;
                        errors.push_back(err);
                    }
                }
            }
        }
    }

    // Check 5: Null pointer dereference
    for (const auto &li : lines) {
        std::string s = li.clean_line;
        for (auto &kv : vars) {
            auto &v = kv.second;
            if (v.is_pointer && v.null_assign_line > 0 && li.line_num >= v.null_assign_line) {
                std::string deref1 = "*" + v.name;
                std::string deref2 = v.name + "->";
                std::string deref3 = v.name + "[";

                size_t p1 = s.find(deref1);
                size_t p2 = s.find(deref2);
                size_t p3 = s.find(deref3);

                if (p1 != std::string::npos || p2 != std::string::npos || p3 != std::string::npos) {
                    size_t pos = (p1 != std::string::npos) ? p1 : ((p2 != std::string::npos) ? p2 : p3);
                    int col = pos + 1 + (p1 != std::string::npos ? 1 : 0);
                    if (li.line_num > v.null_assign_line || col > v.null_assign_col) {
                        Error err;
                        err.id = "nullPointer";
                        err.severity = "error";
                        err.cwe = 476;
                        err.msg = "Null pointer dereference: " + v.name;
                        err.file = filepath;
                        err.line = li.line_num;
                        err.column = col;
                        err.symbol = v.name;
                        err.code_line = li.raw_line;

                        Note n1;
                        n1.file = filepath;
                        n1.line = v.null_assign_line;
                        n1.column = v.null_assign_col;
                        n1.info = "Assignment '" + v.name + "=" + v.null_assign_val + "', assigned value is 0";
                        if (v.null_assign_line > 0 && v.null_assign_line <= (int)lines.size()) {
                            n1.code_line = lines[v.null_assign_line - 1].raw_line;
                        }
                        err.notes.push_back(n1);

                        errors.push_back(err);
                    }
                }
            }
        }
    }

    // Check 6: Division by zero
    std::regex div_zero_lit(R"(/\s*0\b)");
    for (const auto &li : lines) {
        std::smatch match;
        std::string s = li.clean_line;
        if (std::regex_search(s, match, div_zero_lit)) {
            Error err;
            err.id = "zerodiv";
            err.severity = "error";
            err.cwe = 369;
            err.msg = "Division by zero.";
            err.file = filepath;
            err.line = li.line_num;
            err.column = match.position() + 1;
            err.code_line = li.raw_line;
            errors.push_back(err);
        } else {
            for (auto &kv : vars) {
                auto &v = kv.second;
                if (v.zero_assign_line > 0 && li.line_num >= v.zero_assign_line) {
                    std::regex div_var_regex(R"(/\s*\b)" + v.name + R"(\b)");
                    if (std::regex_search(s, match, div_var_regex)) {
                        Error err;
                        err.id = "zerodiv";
                        err.severity = "error";
                        err.cwe = 369;
                        err.msg = "Division by zero.";
                        err.file = filepath;
                        err.line = li.line_num;
                        err.column = match.position() + 1;
                        err.code_line = li.raw_line;

                        Note n1;
                        n1.file = filepath;
                        n1.line = v.zero_assign_line;
                        n1.column = v.zero_assign_col;
                        n1.info = "Assignment '" + v.name + "=0', assigned value is 0";
                        if (v.zero_assign_line > 0 && v.zero_assign_line <= (int)lines.size()) {
                            n1.code_line = lines[v.zero_assign_line - 1].raw_line;
                        }
                        err.notes.push_back(n1);

                        errors.push_back(err);
                    }
                }
            }
        }
    }

    // Check 7: Const Variable Pointer
    for (const auto &kv : vars) {
        const auto &v = kv.second;
        if (v.is_pointer && v.is_assigned && !v.is_modified_via_ptr) {
            Error err;
            err.id = "constVariablePointer";
            err.severity = "style";
            err.cwe = 398;
            err.msg = "Variable '" + v.name + "' can be declared as pointer to const";
            err.file = filepath;
            err.line = v.decl_line;
            err.column = v.decl_col;
            err.symbol = v.name;
            if (v.decl_line > 0 && v.decl_line <= (int)lines.size()) {
                err.code_line = lines[v.decl_line - 1].raw_line;
            }
            errors.push_back(err);
        }
    }

    // Check 8: Unread variable
    for (const auto &kv : vars) {
        const auto &v = kv.second;
        if (v.is_assigned && v.assign_line > 0 && !v.is_read) {
            Error err;
            err.id = "unreadVariable";
            err.severity = "style";
            err.cwe = 563;
            if (v.array_size > 0) {
                err.msg = "Variable '" + v.name + "[" + std::to_string(v.array_size) + "]' is assigned a value that is never used.";
                err.symbol = v.name + "[" + std::to_string(v.array_size) + "]";
            } else {
                err.msg = "Variable '" + v.name + "' is assigned a value that is never used.";
                err.symbol = v.name;
            }
            err.file = filepath;
            err.line = v.assign_line;
            err.column = v.assign_col;
            if (v.assign_line > 0 && v.assign_line <= (int)lines.size()) {
                err.code_line = lines[v.assign_line - 1].raw_line;
            }
            errors.push_back(err);
        }
    }

    // Check 9: Unused functions
    std::regex func_def_regex(R"(\b(void|int|char|float|double|long|short)\s+(\w+)\s*\([^)]*\)\s*\{)");
    std::vector<std::pair<std::string, std::pair<int, int>>> func_defs;
    std::set<std::string> called_funcs;

    for (const auto &li : lines) {
        std::smatch m;
        std::string s = li.clean_line;
        auto f_begin = std::sregex_iterator(s.begin(), s.end(), func_def_regex);
        auto f_end = std::sregex_iterator();
        for (auto it = f_begin; it != f_end; ++it) {
            std::smatch match = *it;
            std::string fname = match[2].str();
            if (fname != "main") {
                func_defs.push_back({fname, {li.line_num, match.position(2) + 1}});
            }
        }

        std::regex call_regex(R"(\b(\w+)\s*\()");
        auto c_begin = std::sregex_iterator(s.begin(), s.end(), call_regex);
        auto c_end = std::sregex_iterator();
        for (auto it = c_begin; it != c_end; ++it) {
            std::smatch match = *it;
            std::string fname = match[1].str();
            for (const auto &fd : func_defs) {
                if (fd.first == fname && li.line_num != fd.second.first) {
                    called_funcs.insert(fname);
                }
            }
        }
    }

    for (const auto &fd : func_defs) {
        if (!called_funcs.count(fd.first)) {
            Error err;
            err.id = "unusedFunction";
            err.severity = "style";
            err.cwe = 561;
            err.msg = "The function '" + fd.first + "' is never used.";
            err.file = filepath;
            err.line = fd.second.first;
            err.column = fd.second.second;
            err.symbol = fd.first;
            if (fd.second.first > 0 && fd.second.first <= (int)lines.size()) {
                err.code_line = lines[fd.second.first - 1].raw_line;
            }
            errors.push_back(err);
        }
    }

    // Sort errors by line and column
    std::sort(errors.begin(), errors.end(), [](const Error &a, const Error &b) {
        if (a.line != b.line) return a.line < b.line;
        return a.column < b.column;
    });

    // Filter by suppressions and inline suppressions
    std::vector<Error> filtered_errors;
    for (const auto &err : errors) {
        if (!opt.is_severity_enabled(err.severity, err.id)) continue;
        if (supp.is_suppressed(err)) continue;

        if (opt.inline_suppr && err.line > 0 && err.line <= (int)lines.size()) {
            std::string supp_id = lines[err.line - 1].inline_suppress_id;
            if (err.line > 1 && supp_id.empty()) {
                supp_id = lines[err.line - 2].inline_suppress_id;
            }
            if (!supp_id.empty() && (supp_id == "*" || supp_id == err.id)) {
                continue;
            }
        }

        filtered_errors.push_back(err);
    }

    return filtered_errors;
}
