#include "formatter.hpp"
#include <iostream>
#include <sstream>

static std::string xml_escape(const std::string &s) {
    std::string res;
    for (char c : s) {
        if (c == '&') res += "&amp;";
        else if (c == '<') res += "&lt;";
        else if (c == '>') res += "&gt;";
        else if (c == '"') res += "&quot;";
        else if (c == '\'') res += "&apos;";
        else res += c;
    }
    return res;
}

static std::string make_caret_line(const std::string &code_line, int col) {
    if (code_line.empty() || col <= 0) return "";
    std::string spaces;
    int cur_col = 1;
    for (char c : code_line) {
        if (cur_col >= col) break;
        if (c == '\t') spaces += '\t';
        else spaces += ' ';
        cur_col++;
    }
    spaces += '^';
    return spaces;
}

void Formatter::print_xml_header() {
    std::cerr << "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n";
    std::cerr << "<results version=\"2\">\n";
    std::cerr << "    <cppcheck version=\"2.19 dev\"/>\n";
    std::cerr << "    <errors>\n";
}

void Formatter::print_xml_footer() {
    std::cerr << "    </errors>\n";
    std::cerr << "</results>\n";
}

std::string Formatter::format_template(const std::string &fmt_in, const Error &err) {
    std::string fmt = fmt_in;
    if (fmt == "default") {
        std::string res = err.file + ":" + std::to_string(err.line) + ":" + std::to_string(err.column) +
                          ": " + err.severity + ": " + err.msg + " [" + err.id + "]\n";
        if (!err.code_line.empty()) {
            res += err.code_line + "\n" + make_caret_line(err.code_line, err.column) + "\n";
        }
        for (const auto &note : err.notes) {
            res += note.file + ":" + std::to_string(note.line) + ":" + std::to_string(note.column) +
                   ": note: " + note.info + "\n";
            if (!note.code_line.empty()) {
                res += note.code_line + "\n" + make_caret_line(note.code_line, note.column) + "\n";
            }
        }
        return res;
    } else if (fmt == "gcc") {
        std::string res = err.file + ":" + std::to_string(err.line) + ":" + std::to_string(err.column) +
                          ": warning: " + err.msg + " [" + err.id + "]\n";
        if (!err.code_line.empty()) {
            res += err.code_line + "\n" + make_caret_line(err.code_line, err.column) + "\n";
        }
        return res;
    } else if (fmt == "cppcheck1") {
        return "[" + err.file + ":" + std::to_string(err.line) + "]: (" + err.severity + ") " + err.msg + "\n";
    } else if (fmt == "vs") {
        return err.file + "(" + std::to_string(err.line) + "): " + err.severity + ": " + err.msg + "\n";
    } else if (fmt == "edit") {
        return err.file + " +" + std::to_string(err.line) + ": " + err.severity + ": " + err.msg + "\n";
    }

    std::string out;
    size_t i = 0;
    while (i < fmt.length()) {
        if (fmt[i] == '\\' && i + 1 < fmt.length()) {
            char next = fmt[i + 1];
            if (next == 'n') out += '\n';
            else if (next == 't') out += '\t';
            else if (next == 'r') out += '\r';
            else out += next;
            i += 2;
        } else if (fmt[i] == '{') {
            size_t end = fmt.find('}', i);
            if (end != std::string::npos) {
                std::string tag = fmt.substr(i + 1, end - i - 1);
                if (tag == "file") out += err.file;
                else if (tag == "line") out += std::to_string(err.line);
                else if (tag == "column") out += std::to_string(err.column);
                else if (tag == "severity") out += err.severity;
                else if (tag == "message") out += err.msg;
                else if (tag == "id") out += err.id;
                else if (tag == "cwe") out += (err.cwe > 0 ? std::to_string(err.cwe) : "");
                else if (tag == "code") {
                    if (!err.code_line.empty()) {
                        out += err.code_line + "\n" + make_caret_line(err.code_line, err.column);
                    }
                } else if (tag.rfind("inconclusive:", 0) == 0) {
                    if (err.inconclusive) out += tag.substr(13);
                } else if (tag == "callstack") {
                    out += "[" + err.file + ":" + std::to_string(err.line) + "]";
                } else {
                    out += "{" + tag + "}";
                }
                i = end + 1;
            } else {
                out += fmt[i++];
            }
        } else {
            out += fmt[i++];
        }
    }
    if (!out.empty() && out.back() != '\n') out += '\n';
    return out;
}

void Formatter::print_error(const Error &err, const Options &opt) {
    if (opt.xml) {
        std::cerr << "        <error id=\"" << xml_escape(err.id) << "\""
                  << " severity=\"" << xml_escape(err.severity) << "\""
                  << " msg=\"" << xml_escape(err.msg) << "\""
                  << " verbose=\"" << xml_escape(err.verbose_msg.empty() ? err.msg : err.verbose_msg) << "\"";
        if (err.cwe > 0) {
            std::cerr << " cwe=\"" << err.cwe << "\"";
        }
        if (!err.file.empty()) {
            std::cerr << " file0=\"" << xml_escape(err.file) << "\"";
        }
        std::cerr << ">\n";

        std::string main_info = "";
        if (err.id == "arrayIndexOutOfBounds") main_info = "Array index out of bounds";
        else if (err.id == "nullPointer") main_info = "Null pointer dereference";
        else if (err.id == "zerodiv") main_info = "Division by zero";

        if (!err.file.empty()) {
            std::cerr << "            <location file=\"" << xml_escape(err.file) << "\""
                      << " line=\"" << err.line << "\""
                      << " column=\"" << err.column << "\"";
            if (!main_info.empty()) {
                std::cerr << " info=\"" << xml_escape(main_info) << "\"";
            }
            std::cerr << "/>\n";
        }

        for (const auto &note : err.notes) {
            if (note.info == "Null pointer dereference" || note.info == "Division by zero") {
                continue;
            }
            std::cerr << "            <location file=\"" << xml_escape(note.file) << "\""
                      << " line=\"" << note.line << "\""
                      << " column=\"" << note.column << "\""
                      << " info=\"" << xml_escape(note.info) << "\"/>\n";
        }

        if (!err.symbol.empty()) {
            std::cerr << "            <symbol>" << xml_escape(err.symbol) << "</symbol>\n";
        }

        std::cerr << "        </error>\n";
    } else {
        std::string formatted = format_template(opt.template_format, err);
        std::cerr << formatted;
    }
}
